import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.siteSettings().getSiteSettings();
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("site_settings");
Map<?, ?> storeDetails = (Map<?, ?>) settings.get("store_details");
Map<?, ?> brandKit = (Map<?, ?>) settings.get("brand_kit");
Map<?, ?> dateTime = (Map<?, ?>) settings.get("date_time");
System.out.println(storeDetails.get("company_name") + " " + storeDetails.get("email"));
System.out.println(brandKit.get("palette_name") + " " + ((Map<?, ?>) brandKit.get("colors")).get("primary"));
System.out.println(((Map<?, ?>) dateTime.get("admin")).get("time_zone"));

